-- V7__seed_chmsu_curriculum_catalog.sql
-- Flyway Seed Migration: CHMSU Master Course Catalog, Colleges, Programs, CILOs, Curricula, and Prerequisites
-- Sourced from: CHMSU_Curriculum_Master_Catalog_CILOs_Prerequisites_Updated.xlsx

SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- 1. Seed Academic Colleges / Departments
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE name = VALUES(name), is_active = TRUE;

-- -----------------------------------------------------------------------------
-- 2. Seed Degree Programs
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE name = VALUES(name), major = VALUES(major), ched_cmo_reference = VALUES(ched_cmo_reference), total_units_required = VALUES(total_units_required);

-- -----------------------------------------------------------------------------
-- 3. Seed Master Course Catalog
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE title = VALUES(title), lecture_units = VALUES(lecture_units), lab_units = VALUES(lab_units), credit_units = VALUES(credit_units), contact_hours_lec = VALUES(contact_hours_lec), contact_hours_lab = VALUES(contact_hours_lab), category = VALUES(category);

-- -----------------------------------------------------------------------------
-- 4. Seed Academic Curricula Benchmarks
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE name = VALUES(name), status = VALUES(status), effective_academic_year = VALUES(effective_academic_year);

-- -----------------------------------------------------------------------------
-- 5. Seed Curriculum Course Offerings & Term Mappings
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE year_level = VALUES(year_level), semester = VALUES(semester);

-- -----------------------------------------------------------------------------
-- 6. Seed Course Intended Learning Outcomes (CILOs)
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE description = VALUES(description), blooms_level = VALUES(blooms_level);

-- -----------------------------------------------------------------------------
-- 7. Seed Course Prerequisites & Co-requisites
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE rule_type = VALUES(rule_type), min_grade_required = VALUES(min_grade_required);

SET FOREIGN_KEY_CHECKS = 1;